// Contornos SVG de las 16 alcaldías de Ciudad de México + 19 municipios
// conurbados del Estado de México (Zona Metropolitana del Valle de México) —
// proyectados y simplificados (Douglas-Peucker) a partir de los polígonos
// oficiales de INEGI (Marco Geoestadístico), obtenidos vía el espejo
// público github.com/elbic/Mexican-Municipalities. Datos de límites
// territoriales de un organismo público, no una obra creativa protegida.
//
// `code` es el slug CANÓNICO del catálogo real de ubicaciones (tabla
// `locations` en la API, servida por GET /api/locations — ver
// apps/cms/src/lib/locations.ts y apps/api/src/db/seed-locations.ts), el
// mismo que usan noticias/alertas/eventos/lugares en su campo
// `alcaldiaSlug`. Antes este archivo usaba códigos INEGI de 5 dígitos con
// nombres largos ("naucalpan-de-juarez") que no coincidían con ese
// catálogo — se alinearon para poder preseleccionar la ubicación real al
// generar contenido desde este mapa (ver EntidadesExplorer/centroIaHref).
export interface ZmvmMunicipioShape {
  code: string;
  name: string;
  parentState: "cmx" | "mex";
  path: string;
}

